import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

import org.springframework.stereotype.Service;

/**
 * Keeps the messages sent so far in memory, shared by all visits to the contact view.
 */
@Service
public class MessageService {

    private final List<Message> messages = new CopyOnWriteArrayList<>();

    public void add(Message message) {
        messages.add(message);
    }

    /**
     * @return a snapshot of all sent messages, newest first
     */
    public List<Message> findAllNewestFirst() {
        List<Message> newestFirst = new ArrayList<>(messages);
        Collections.reverse(newestFirst);
        return newestFirst;
    }
}
