class ContactViewBrowserTest {

    @Value("${local.server.port}")
    private int port;

    private static Playwright playwright;
    private static Browser browser;
    private Page page;

    @BeforeAll
    static void startBrowser() {
        playwright = Playwright.create();
        browser = playwright.chromium().launch();
    }

    @AfterAll
    static void stopBrowser() {
        browser.close();
        playwright.close();
    }

    @Test
    void sendsMessageAndAsksBeforeLeavingWithTypedText() {
        page = browser.newPage();
        page.navigate("http://localhost:" + port + "/contact");
        page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("Contact"))
                .waitFor(new Locator.WaitForOptions().setState(WaitForSelectorState.VISIBLE));

        Locator send = page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send"));
        assertTrue(send.isEnabled());

        page.getByLabel("Name").fill("Browser Tester");
        page.getByLabel("Phone").fill("0401234567");
        page.getByLabel("Message").fill("Sent from a browser");
        page.getByLabel("Message").press("Control+Enter");
        page.getByLabel("Message").press("Tab");
        send.click();

        page.getByText("Message sent").waitFor();
        assertEquals("", page.getByLabel("Name").inputValue());
        assertTrue(!send.isEnabled());
        assertTrue(page.getByRole(AriaRole.GRID).getByText("Sent from a browser").count() >= 1);

        page.getByLabel("Name").fill("Typed");
        assertTrue(send.isEnabled());

        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
        page.getByRole(AriaRole.DIALOG).waitFor();
        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
        assertEquals("Typed", page.getByLabel("Name").inputValue());

        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
        page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About")).waitFor();
        page.close();
    }
}
