+package com.example.contact;
+
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
+
+    private final MessageService messages;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<Message> grid = new Grid<>();
+
+    private final Dialog confirmLeave = new Dialog();
+    private BeforeLeaveEvent.ContinueNavigationAction pendingNavigation;
+
+    public ContactView(MessageService messages) {
+        this.messages = messages;
+
+        // Report every edit straight away, so that editing re-enables Send without waiting for blur
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        name.addValueChangeListener(e -> send.setEnabled(true));
+        email.addValueChangeListener(e -> send.setEnabled(true));
+        phone.addValueChangeListener(e -> send.setEnabled(true));
+        message.addValueChangeListener(e -> send.setEnabled(true));
+
+        send.addClickListener(e -> sendMessage());
+        Shortcuts.addShortcutListener(this, this::sendMessage, Key.ENTER);
+
+        confirmLeave.setHeaderTitle("Discard your message?");
+        confirmLeave.add(new Paragraph("You have typed something that has not been sent yet."));
+        Button keepEditing = new Button("Keep editing", e -> keepEditing());
+        Button discard = new Button("Discard", e -> discard());
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        confirmLeave.getFooter().add(keepEditing, discard);
+        // Dismissing the dialog with Esc or an outside click also keeps the user here
+        confirmLeave.addDialogCloseActionListener(e -> keepEditing());
+        add(confirmLeave);
+
+        grid.addColumn(Message::name).setHeader("Name");
+        grid.addColumn(Message::email).setHeader("Email");
+        grid.addColumn(Message::phone).setHeader("Phone");
+        grid.addColumn(Message::message).setHeader("Message").setFlexGrow(1);
+        grid.setItems(messages.findAllNewestFirst());
+
+        add(
+                new H1("Contact"),
+                new RouterLink("About", AboutView.class),
+                new FormLayout(name, email, phone, message),
+                new HorizontalLayout(send),
+                grid);
+    }
+
+    private void sendMessage() {
+        if (!validate()) {
+            return;
+        }
+        messages.add(new Message(
+                name.getValue().trim(),
+                email.getValue().trim(),
+                phone.getValue().trim(),
+                message.getValue().trim()));
+        grid.setItems(messages.findAllNewestFirst());
+
+        // Clearing the fields fires their value change listeners, which enable Send,
+        // so Send is disabled only after they have been cleared
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+
+        Notification.show("Message sent");
+    }
+
+    private boolean validate() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+
+        boolean valid = true;
+
+        if (name.getValue().isBlank()) {
+            invalid(name, "Name is required");
+            valid = false;
+        }
+
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        if (!emailValue.isEmpty() && !EMAIL.matcher(emailValue).matches()) {
+            invalid(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            invalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        String messageValue = message.getValue().trim();
+        if (messageValue.isEmpty()) {
+            invalid(message, "Message is required");
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            invalid(message, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private static void invalid(HasValidation field, String errorMessage) {
+        field.setInvalid(true);
+        field.setErrorMessage(errorMessage);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasInput()) {
+            pendingNavigation = event.postpone();
+            confirmLeave.open();
+        }
+    }
+
+    private boolean hasInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    private void keepEditing() {
+        // Cancelling, rather than just forgetting the action, releases the navigation
+        // on the client; otherwise the client router ignores later link clicks
+        var navigation = pendingNavigation;
+        pendingNavigation = null;
+        confirmLeave.close();
+        if (navigation != null) {
+            navigation.cancel();
+        }
+    }
+
+    private void discard() {
+        var navigation = pendingNavigation;
+        pendingNavigation = null;
+        confirmLeave.close();
+        if (navigation != null) {
+            navigation.proceed();
+        }
+    }
+}
